// AI-generated by GPT 6.1 Sol (OpenAI) via OpenCode for the camera-adjustments change.
import assert from 'node:assert/strict';
import {
  CAMERA_PROFILE_SCHEMA, CAMERA_PROFILE_VERSION, MAX_CAMERA_PROFILE_BYTES,
  DEFAULT_FINE_TUNE, DEFAULT_IMAGE_ADJUSTMENTS,
  normalizeFineTune, normalizeImageAdjustments,
  parseCameraProfile, serializeCameraProfile, fineTunePoint, inverseFineTunePoint,
} from '../src/cameraProfile';
import type { CameraProfileInput } from '../src/cameraProfile';

const fixed: CameraProfileInput = {
  mount: 'fixed', name: 'Overhead', cameraLabel: 'USB camera', width: 1920, height: 1080,
  calib: { w: 1920, h: 1080, H: [0.01, 0, -1, 0, -0.01, 1, 0, 0, 1], k1: 0, k2: 0, err: 0.2, maxErr: 0.4, bedW: 200, bedH: 100, date: '2026-11-03' },
  fineTune: { ...DEFAULT_FINE_TUNE }, image: { ...DEFAULT_IMAGE_ADJUSTMENTS },
};
const parsed = parseCameraProfile(serializeCameraProfile(fixed));
assert.deepEqual(parsed, { schema: CAMERA_PROFILE_SCHEMA, version: CAMERA_PROFILE_VERSION, ...fixed });
assert.notEqual(parsed.calib.H, fixed.calib.H);
const head = { ...fixed, mount: 'head' as const, calib: { ...fixed.calib, head: { x: 20, y: 30 } } };
assert.deepEqual(parseCameraProfile(serializeCameraProfile(head)).calib.head, { x: 20, y: 30 });

function reject(change: (p: any) => void): void {
  const p = JSON.parse(serializeCameraProfile(fixed));
  change(p);
  assert.throws(() => parseCameraProfile(JSON.stringify(p)));
}
reject((p) => p.schema = 'unknown');
reject((p) => p.version = 2);
reject((p) => p.mount = 'other');
reject((p) => p.mount = 'head');
reject((p) => p.calib.head = { x: 0, y: 0 });
reject((p) => p.calib.H = [1, 2, 3, 2, 4, 6, 0, 0, 1]);
reject((p) => p.calib.H = [1, 0]);
reject((p) => p.calib.H[0] = '1');
reject((p) => p.calib.H[0] = null);
reject((p) => p.width = 100001);
reject((p) => p.height = 1.5);
reject((p) => p.calib.bedW = 0);
reject((p) => p.calib.bedH = 100001);
reject((p) => p.calib.k1 = 101);
reject((p) => p.calib.err = -1);
reject((p) => p.name = 'x'.repeat(257));
reject((p) => p.cameraLabel = 'x'.repeat(1025));
reject((p) => p.calib.date = 'x'.repeat(129));
reject((p) => p.fineTune.scaleX = 0);
reject((p) => p.fineTune.scaleY = 11);
reject((p) => p.fineTune.rotation = 181);
reject((p) => p.fineTune.offsetX = 10001);
reject((p) => delete p.fineTune.offsetY);
reject((p) => p.image.gamma = 0);
reject((p) => p.image.brightness = 4);
reject((p) => p.image.contrast = -1);
reject((p) => p.image.saturation = '1');
reject((p) => p.image.grayscale = 1);
assert.throws(() => serializeCameraProfile({ ...fixed, calib: { ...fixed.calib, k2: Infinity } }));
assert.throws(() => serializeCameraProfile({ ...head, calib: { ...head.calib, head: { x: NaN, y: 0 } } }));
assert.throws(() => parseCameraProfile('{'));
assert.throws(() => parseCameraProfile(' '.repeat(MAX_CAMERA_PROFILE_BYTES + 1)));
assert.throws(() => parseCameraProfile('"' + 'é'.repeat(MAX_CAMERA_PROFILE_BYTES / 2) + '"'));
assert.throws(() => parseCameraProfile(serializeCameraProfile(fixed).replace('"k1": 0', '"k1": 1e999')));

const extras = JSON.parse(serializeCameraProfile(fixed));
extras.deviceId = 'secret'; extras.token = 'secret'; extras.connection = { host: 'secret' };
extras.calib.deviceconfig = 'secret'; extras.fineTune.extra = 'secret';
extras.__proto__ = { polluted: true };
const clean = parseCameraProfile(JSON.stringify(extras));
assert.equal(serializeCameraProfile(clean).includes('secret'), false);
assert.equal(Object.prototype.hasOwnProperty.call(clean, 'deviceId'), false);
const poison = JSON.parse(serializeCameraProfile(fixed).replace('"name": "Overhead"', '"__proto__": {"polluted":true}, "name": "Overhead"'));
assert.equal(Object.prototype.hasOwnProperty.call(parseCameraProfile(JSON.stringify(poison)), '__proto__'), false);
assert.equal(({} as any).polluted, undefined);
const inherited = Object.create(fixed);
assert.throws(() => serializeCameraProfile(inherited));
const getter = { ...fixed };
Object.defineProperty(getter, 'name', { get() { throw new Error('Getter must not run'); } });
assert.throws(() => serializeCameraProfile(getter), /Invalid camera profile/);

assert.deepEqual(normalizeFineTune(null), DEFAULT_FINE_TUNE);
assert.deepEqual(normalizeFineTune({ scaleX: 0, scaleY: Infinity, rotation: '2', offsetX: 3 }), { ...DEFAULT_FINE_TUNE, offsetX: 3 });
assert.deepEqual(normalizeImageAdjustments({ brightness: -1, gamma: NaN, grayscale: 'yes' }), DEFAULT_IMAGE_ADJUSTMENTS);
assert.deepEqual(normalizeImageAdjustments({ brightness: 0, contrast: 3, saturation: 0, gamma: 5, grayscale: true }), { brightness: 0, contrast: 3, saturation: 0, gamma: 5, grayscale: true });
assert.deepEqual(normalizeFineTune(Object.create({ offsetX: 99 })), DEFAULT_FINE_TUNE);

function close(a: { x: number; y: number }, b: { x: number; y: number }): void {
  assert.ok(Math.abs(a.x - b.x) < 1e-9 && Math.abs(a.y - b.y) < 1e-9, `${JSON.stringify(a)} != ${JSON.stringify(b)}`);
}
close(fineTunePoint({ x: 12, y: 34 }, DEFAULT_FINE_TUNE, 200, 100), { x: 12, y: 34 });
close(fineTunePoint({ x: 110, y: 50 }, { ...DEFAULT_FINE_TUNE, rotation: 90 }, 200, 100), { x: 100, y: 60 });
close(fineTunePoint({ x: 110, y: 60 }, { ...DEFAULT_FINE_TUNE, scaleX: 2, scaleY: 3 }, 200, 100), { x: 120, y: 80 });
const tune = { offsetX: 7, offsetY: -4, scaleX: 2, scaleY: 3, rotation: 90 };
close(fineTunePoint({ x: 100, y: 50 }, tune, 200, 100), { x: 107, y: 46 });
close(fineTunePoint({ x: 110, y: 60 }, tune, 200, 100), { x: 77, y: 66 });
for (const rotation of [-180, -90, -23, 0, 90, 180]) {
  for (const scaleX of [0.1, 1, 10]) {
    const t = { ...tune, rotation, scaleX };
    for (const p of [{ x: 0, y: 0 }, { x: 200, y: 100 }, { x: -5, y: 231 }]) {
      close(inverseFineTunePoint(fineTunePoint(p, t, 200, 100), t, 200, 100), p);
      close(fineTunePoint(inverseFineTunePoint(p, t, 200, 100), t, 200, 100), p);
    }
  }
}
console.log('Camera profile tests passed');
